-- =====================================================================
-- Hand-written: CHECK constraints
-- =====================================================================

ALTER TABLE "users" ADD CONSTRAINT "users_email_lowercase" CHECK ("email" = lower("email"));

ALTER TABLE "taste_profile_versions" ADD CONSTRAINT "taste_profile_versions_version_no_positive" CHECK ("version_no" >= 1);
ALTER TABLE "profile_ratings" ADD CONSTRAINT "profile_ratings_rating_range" CHECK ("rating" BETWEEN 1 AND 5);
ALTER TABLE "rating_import_rows" ADD CONSTRAINT "rating_import_rows_rating_range" CHECK ("rating" BETWEEN 1 AND 5);
ALTER TABLE "rating_imports" ADD CONSTRAINT "rating_imports_counts" CHECK ("total_rows" >= 0 AND "matched_count" BETWEEN 0 AND "total_rows");

ALTER TABLE "edition_genres" ADD CONSTRAINT "edition_genres_votes_nonnegative" CHECK ("votes" >= 0);
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_rating_range" CHECK ("rating" IS NULL OR "rating" BETWEEN 1 AND 5);
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_text_length_nonnegative" CHECK ("text_length" IS NULL OR "text_length" >= 0);
ALTER TABLE "review_fetches" ADD CONSTRAINT "review_fetches_rating_average_range" CHECK ("rating_average" IS NULL OR "rating_average" BETWEEN 1 AND 5);
ALTER TABLE "review_fetches" ADD CONSTRAINT "review_fetches_counts_nonnegative" CHECK ("review_count" >= 0 AND ("rating_count" IS NULL OR "rating_count" >= 0));

-- RES-3: no written verdict without usable evidence.
ALTER TABLE "public_analyses" ADD CONSTRAINT "public_analyses_no_summary_without_evidence"
  CHECK ("evidence_state" NOT IN ('insufficient', 'unavailable') OR "summary" IS NULL);

-- An evidence item points at exactly what its kind says.
ALTER TABLE "evidence_items" ADD CONSTRAINT "evidence_items_position_positive" CHECK ("position" >= 1);
ALTER TABLE "evidence_items" ADD CONSTRAINT "evidence_items_kind_shape" CHECK (
  ("kind" = 'review' AND "review_id" IS NOT NULL AND "source_id" IS NULL AND "review_count" IS NULL)
  OR ("kind" = 'description' AND "review_id" IS NULL AND "source_id" IS NULL AND "review_count" IS NULL)
  OR ("kind" = 'source_aggregate' AND "review_id" IS NULL AND "source_id" IS NOT NULL AND "review_count" > 0)
);

-- finished_at is set exactly when the analysis is no longer running.
ALTER TABLE "analyses" ADD CONSTRAINT "analyses_finished_when_not_running"
  CHECK (("status" = 'running') = ("finished_at" IS NULL));

-- Personal match: a score exists only when scored, on the 1 to 5 scale (D-007),
-- and a scored result always records its model and profile versions (MODEL-3).
ALTER TABLE "personal_analyses" ADD CONSTRAINT "personal_analyses_score_iff_scored"
  CHECK (("outcome" = 'scored') = ("score" IS NOT NULL));
ALTER TABLE "personal_analyses" ADD CONSTRAINT "personal_analyses_score_range"
  CHECK ("score" IS NULL OR "score" BETWEEN 1 AND 5);
ALTER TABLE "personal_analyses" ADD CONSTRAINT "personal_analyses_scored_has_versions"
  CHECK ("outcome" <> 'scored' OR ("model_version_id" IS NOT NULL AND "taste_profile_version_id" IS NOT NULL AND "confidence" IS NOT NULL));
ALTER TABLE "personal_similar_books" ADD CONSTRAINT "personal_similar_books_rating_range" CHECK ("your_rating" BETWEEN 1 AND 5);
ALTER TABLE "personal_similar_books" ADD CONSTRAINT "personal_similar_books_rank_positive" CHECK ("rank" >= 1);

-- Feedback on the personal match is stored with the versions it judged (spec 6, FB-1).
ALTER TABLE "feedback" ADD CONSTRAINT "feedback_personal_has_versions"
  CHECK ("target" <> 'personal' OR ("taste_profile_version_id" IS NOT NULL AND "model_version_id" IS NOT NULL));

