-- Hand-written: duplicate requests join the running analysis (spec 10)
-- =====================================================================

CREATE UNIQUE INDEX "analyses_one_running_per_request" ON "analyses" (
  "user_id",
  "edition_id",
  COALESCE("taste_profile_version_id", '00000000-0000-0000-0000-000000000000'::uuid)
) WHERE "status" = 'running';

-- =====================================================================
-- Hand-written: immutability (ONB-4, MODEL-1, MODEL-3)
-- Saved taste profiles and personal results never change. Deleting is still
-- allowed so delete-my-data works (SEC-3).
-- =====================================================================

CREATE FUNCTION "bookie_reject_update"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  -- Default SQLSTATE P0001 (raise_exception) keeps this message visible to callers.
  RAISE EXCEPTION 'Rows in % are immutable', TG_TABLE_NAME;
END
$$;

-- Child rows may only be written in the same transaction that created their
-- parent, so nobody can add a rating to an old version later.
-- Arguments: parent table, column in the child holding the parent id.
CREATE FUNCTION "bookie_require_parent_created_in_this_transaction"() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  parent_xmin xid;
BEGIN
  EXECUTE format('SELECT xmin FROM %I WHERE id = $1', TG_ARGV[0])
    INTO parent_xmin
    USING (to_jsonb(NEW) ->> TG_ARGV[1])::uuid;
  IF parent_xmin IS DISTINCT FROM pg_current_xact_id()::xid THEN
    RAISE EXCEPTION 'Rows in % can only be added in the transaction that created their %', TG_TABLE_NAME, TG_ARGV[0];
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "taste_profile_versions_immutable" BEFORE UPDATE ON "taste_profile_versions"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();
CREATE TRIGGER "profile_ratings_immutable" BEFORE UPDATE ON "profile_ratings"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();
CREATE TRIGGER "profile_genre_preferences_immutable" BEFORE UPDATE ON "profile_genre_preferences"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();
CREATE TRIGGER "profile_theme_avoidances_immutable" BEFORE UPDATE ON "profile_theme_avoidances"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();
CREATE TRIGGER "personal_analyses_immutable" BEFORE UPDATE ON "personal_analyses"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();
CREATE TRIGGER "personal_similar_books_immutable" BEFORE UPDATE ON "personal_similar_books"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();
CREATE TRIGGER "personal_trait_fits_immutable" BEFORE UPDATE ON "personal_trait_fits"
  FOR EACH ROW EXECUTE FUNCTION "bookie_reject_update"();

CREATE TRIGGER "profile_ratings_sealed" BEFORE INSERT ON "profile_ratings"
  FOR EACH ROW EXECUTE FUNCTION "bookie_require_parent_created_in_this_transaction"('taste_profile_versions', 'taste_profile_version_id');
CREATE TRIGGER "profile_genre_preferences_sealed" BEFORE INSERT ON "profile_genre_preferences"
  FOR EACH ROW EXECUTE FUNCTION "bookie_require_parent_created_in_this_transaction"('taste_profile_versions', 'taste_profile_version_id');
CREATE TRIGGER "profile_theme_avoidances_sealed" BEFORE INSERT ON "profile_theme_avoidances"
  FOR EACH ROW EXECUTE FUNCTION "bookie_require_parent_created_in_this_transaction"('taste_profile_versions', 'taste_profile_version_id');
CREATE TRIGGER "personal_similar_books_sealed" BEFORE INSERT ON "personal_similar_books"
  FOR EACH ROW EXECUTE FUNCTION "bookie_require_parent_created_in_this_transaction"('personal_analyses', 'personal_analysis_id');
CREATE TRIGGER "personal_trait_fits_sealed" BEFORE INSERT ON "personal_trait_fits"
  FOR EACH ROW EXECUTE FUNCTION "bookie_require_parent_created_in_this_transaction"('personal_analyses', 'personal_analysis_id');

